*/
scwin.slc_disclsEduApctTpCd_onchange = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_disclsEduApctTpCd_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.change(selfVar);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16501.slc_disclsEduApctTpCd_onchange' }); }
};

