/**
 * @event
 * @name scwin.grd_EduAppResultList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_EduAppResultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_EduAppResultList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_EduAppResultList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "chbEdu") { if (typeof scwin.checkAll === 'function') { scwin.checkAll(); } else { console.error('[sdd] 행 동작 미정의: scwin.checkAll (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.checkAll'); } return; }
        if (r["disclsEduApctTpCd"] === '81') { if (typeof scwin.searchRspnDetail === 'function') { await scwin.searchRspnDetail(r["disclsEduApplSeq"], r["chrgTpCd"], r["disclsBzChrgAssgnDd"], r["seq"], r["isurCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.searchRspnDetail (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.searchRspnDetail'); } return; }
        if (r["disclsEduApctTpCd"] === '82') { if (typeof scwin.searchChrgDetail === 'function') { await scwin.searchChrgDetail(r["disclsEduApplSeq"], r["seq"], r["isurCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.searchChrgDetail (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.searchChrgDetail'); } return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_EduAppResultList.oncellclick' });
    }
};

