/**
 * @method
 * @name scwin.grd_EduAppResultList_fmt_disclsEduCrsNm
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_EduAppResultList_fmt_disclsEduCrsNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_EduAppResultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "ldMktTpCd") ?? '') : '');
        if (v === '6') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "disclsEduCrsNm") : '') ?? '') + '</a>'; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "disclsEduCrsNm") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_EduAppResultList.disclsEduCrsNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.check
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.check = function () {
    /* sdd-asis-lifecycle:begin check — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let roundRealVal = "";
    const roundVal = $c.util.getComponent('slc_sltEduRnd').getValue();
    const roundVal1 = $c.util.getComponent('slc_sltEduRnd1').getValue();
    const roundVal2 = $c.util.getComponent('slc_sltEduRnd2').getValue();
    const roundVal3 = $c.util.getComponent('slc_sltEduRnd3').getValue();
    const roundVal4 = $c.util.getComponent('slc_sltEduRnd4').getValue();
    const roundVal5 = $c.util.getComponent('slc_sltEduRnd5').getValue();
    const roundVal6 = $c.util.getComponent('slc_sltEduRnd6').getValue();
    const r_temp = $c.util.getComponent('slc_disclsEduApctTpCd').getValue();
    if (r_temp === "%") {
        roundRealVal = roundVal;
    } else {
        if (r_temp === "11") {
            roundRealVal = roundVal1;
        } else {
            if (r_temp === "12") {
                roundRealVal = roundVal2;
            } else {
                if (r_temp === "41") {
                    roundRealVal = roundVal3;
                } else {
                    if (r_temp === "42") {
                        roundRealVal = roundVal4;
                    } else {
                        if (r_temp === "81") {
                            roundRealVal = roundVal5;
                        } else {
                            if (r_temp === "82") {
                                roundRealVal = roundVal6;
                            }
                        }
                    }
                }
            }
        }
    }
    $c.util.getComponent('dma_SearchReq').set('disclsEduApplSeq', roundRealVal);
    /* sdd-asis-lifecycle:end */
};


